// Search the entire trace, across all time, for a user-specified byte pattern.
//@category Debugger  








using docking;
using docking.widgets.table;
using ghidra.app.script;
using ghidra.app.services;
using ghidra.app.services;
using ghidra.app.services.DebuggerTraceManagerService;
using ghidra.async;
using ghidra.debug.api.tracemgr;
using ghidra.framework.plugintool;
using ghidra.program.model.address;
using ghidra.trace.model;
using ghidra.trace.model.memory;

public class SearchBytesAcrossTime : GhidraScript {
	public record Row(Address address, long startSnap, long endSnap) {
		Row(TraceAddressSnapRange match) : this(match.getRange().getMinAddress(), match.getLifespan().lmin(),
					match.getLifespan().lmax())
    {
		}
	}

	private static class ResultsProvider : ComponentProvider {
		private JComponent component;

		ResultsProvider(PluginTool tool, string title, List<Row> rows) : base(tool, title, typeof(ResultsProvider).getSimpleName())
    {

			AnyObjectTableModel<Row> model =
					new("Matches", typeof(Row), "startSnap", "endSnap",
							"address");
			model.setModelData(rows);
			GTable table = new GTable(model);

			table.addMouseListener(new _Anon_MouseAdapter_1());

			GTableFilterPanel<Row> filterPanel = new(table, model);

			JPanel panel = new JPanel(new BorderLayout());
			panel.add(new JScrollPane(table));
			panel.add(filterPanel, BorderLayout.SOUTH);

			component = panel;
			setTransient();
			setVisible(true);
		}

		private void navigateTo(PluginTool tool, long snap, Address address) {
			DebuggerTraceManagerService traceManager =
					tool.getService(typeof(DebuggerTraceManagerService));
			DebuggerListingService listingService = tool.getService(typeof(DebuggerListingService));

			DebuggerCoordinates coords = traceManager.getCurrent().snap(snap);

			traceManager.activateAndNotify(coords, ActivationCause.USER)
					.thenRunAsync(() => listingService.goTo(address, true),
							AsyncUtils.SWING_EXECUTOR);
		}

		/* @Override */
		public JComponent getComponent() {
			return component;
		}
	}

	/* @Override */
	protected void run()
    {
		DebuggerTraceManagerService traceManager =
				state.getTool().getService(typeof(DebuggerTraceManagerService));
		Trace trace = traceManager.getCurrentTrace();
		if (trace == null) {
			printerr("No trace is active");
			return;
		}

		byte[] pattern = askBytes("Search Across Time", "Enter byte pattern to search for:");
		if (pattern == null || pattern.length == 0) {
			printerr("No pattern given");
			return;
		}

		TraceMemoryManager mem = trace.getMemoryManager();

		List<Row> rows = new();

		// This searches the default address space, if your architecture uses other address spaces
		// this needs to be updated.
		AddressRange fullRange = new AddressRangeImpl(toAddr(0L), toAddr(0xFFFF_FFFF_FFFF_FFFFL));
		List<TraceAddressSnapRange> bytesAcrossLifespan =
				mem.findBytesAcrossLifespan(Lifespan.ALL, fullRange, pattern, monitor);

		foreach (TraceAddressSnapRange traceAddressSnapRange in bytesAcrossLifespan) {
			rows.add(new Row(traceAddressSnapRange));
		}
		
		println("Found " + rows.size() + " match(es)");
		new ResultsProvider(state.getTool(), "Search Across Time Results MEMORY_BLOCKS", rows);
	}

	internal class _Anon_MouseAdapter_1 : MouseAdapter
	{

				/* @Override */
				public void mouseClicked(MouseEvent e) {
					if (e.getClickCount() != 2) {
						return;
					}
					int viewRow = table.getSelectedRow();
					if (viewRow == -1) {
						return;
					}
					int modelRow = table.convertRowIndexToModel(viewRow);
					Row row = rows.get(modelRow);
					navigateTo(tool, row.startSnap, row.address);
				}
			
	}

}
